require "crass"

# A parse tree, printed the same way on both sides: every Hash with its
# keys sorted, every leaf by inspect.
def dump(v, out)
  if v.is_a?(Hash)
    out << "{"
    v.keys.sort_by { |k| k.to_s }.each do |k|
      out << k.to_s << "="
      dump(v[k], out)
      out << " "
    end
    out << "}"
  elsif v.is_a?(Array)
    out << "["
    v.each do |e|
      dump(e, out)
      out << ","
    end
    out << "]"
  else
    out << v.inspect
  end
  out
end

